class MenuItem extends DataClass implements Insertable<MenuItem> {
  final String id;
  final String serviceId;
  final String displayName;
  final String? stationName;
  final String? rawText;
  final String? imagePath;
  final String evidenceGrade;
  final String itemStatus;
  final DateTime createdAt;
  final DateTime updatedAt;

  /// 这个窗口一份大概多少克（可空；分析时估或用户填）。
  final double? servingGrams;

  /// 结构化标签 JSON（清淡/辣/汤/面/油炸/餐次…，docs/39 §8）。
  final String tagsJson;

  /// 配料 JSON：`[{name, source, confidence}]`，source = user|ai|dictionary。
  /// **过敏原不单独存，由食材推导**（docs/40 §2.5）。
  final String ingredientsJson;
  const MenuItem({
    required this.id,
    required this.serviceId,
    required this.displayName,
    this.stationName,
    this.rawText,
    this.imagePath,
    required this.evidenceGrade,
    required this.itemStatus,
    required this.createdAt,
    required this.updatedAt,
    this.servingGrams,
    required this.tagsJson,
    required this.ingredientsJson,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['service_id'] = Variable<String>(serviceId);
    map['display_name'] = Variable<String>(displayName);
    if (!nullToAbsent || stationName != null) {
      map['station_name'] = Variable<String>(stationName);
    }
    if (!nullToAbsent || rawText != null) {
      map['raw_text'] = Variable<String>(rawText);
    }
    if (!nullToAbsent || imagePath != null) {
      map['image_path'] = Variable<String>(imagePath);
    }
    map['evidence_grade'] = Variable<String>(evidenceGrade);
    map['item_status'] = Variable<String>(itemStatus);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    if (!nullToAbsent || servingGrams != null) {
      map['serving_grams'] = Variable<double>(servingGrams);
    }
    map['tags_json'] = Variable<String>(tagsJson);
    map['ingredients_json'] = Variable<String>(ingredientsJson);
    return map;
  }

  MenuItemsCompanion toCompanion(bool nullToAbsent) {
    return MenuItemsCompanion(
      id: Value(id),
      serviceId: Value(serviceId),
      displayName: Value(displayName),
      stationName: stationName == null && nullToAbsent
          ? const Value.absent()
          : Value(stationName),
      rawText: rawText == null && nullToAbsent
          ? const Value.absent()
          : Value(rawText),
      imagePath: imagePath == null && nullToAbsent
          ? const Value.absent()
          : Value(imagePath),
      evidenceGrade: Value(evidenceGrade),
      itemStatus: Value(itemStatus),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
      servingGrams: servingGrams == null && nullToAbsent
          ? const Value.absent()
          : Value(servingGrams),
      tagsJson: Value(tagsJson),
      ingredientsJson: Value(ingredientsJson),
    );
  }

  factory MenuItem.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return MenuItem(
      id: serializer.fromJson<String>(json['id']),
      serviceId: serializer.fromJson<String>(json['serviceId']),
      displayName: serializer.fromJson<String>(json['displayName']),
      stationName: serializer.fromJson<String?>(json['stationName']),
      rawText: serializer.fromJson<String?>(json['rawText']),
      imagePath: serializer.fromJson<String?>(json['imagePath']),
      evidenceGrade: serializer.fromJson<String>(json['evidenceGrade']),
      itemStatus: serializer.fromJson<String>(json['itemStatus']),
      createdAt: serializer.fromJson<DateTime>(json['createdAt']),
      updatedAt: serializer.fromJson<DateTime>(json['updatedAt']),
      servingGrams: serializer.fromJson<double?>(json['servingGrams']),
      tagsJson: serializer.fromJson<String>(json['tagsJson']),
      ingredientsJson: serializer.fromJson<String>(json['ingredientsJson']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<String>(id),
      'serviceId': serializer.toJson<String>(serviceId),
      'displayName': serializer.toJson<String>(displayName),
      'stationName': serializer.toJson<String?>(stationName),
      'rawText': serializer.toJson<String?>(rawText),
      'imagePath': serializer.toJson<String?>(imagePath),
      'evidenceGrade': serializer.toJson<String>(evidenceGrade),
      'itemStatus': serializer.toJson<String>(itemStatus),
      'createdAt': serializer.toJson<DateTime>(createdAt),
      'updatedAt': serializer.toJson<DateTime>(updatedAt),
      'servingGrams': serializer.toJson<double?>(servingGrams),
      'tagsJson': serializer.toJson<String>(tagsJson),
      'ingredientsJson': serializer.toJson<String>(ingredientsJson),
    };
  }

  MenuItem copyWith({
    String? id,
    String? serviceId,
    String? displayName,
    Value<String?> stationName = const Value.absent(),
    Value<String?> rawText = const Value.absent(),
    Value<String?> imagePath = const Value.absent(),
    String? evidenceGrade,
    String? itemStatus,
    DateTime? createdAt,
    DateTime? updatedAt,
    Value<double?> servingGrams = const Value.absent(),
    String? tagsJson,
    String? ingredientsJson,
  }) => MenuItem(
    id: id ?? this.id,
    serviceId: serviceId ?? this.serviceId,
    displayName: displayName ?? this.displayName,
    stationName: stationName.present ? stationName.value : this.stationName,
    rawText: rawText.present ? rawText.value : this.rawText,
    imagePath: imagePath.present ? imagePath.value : this.imagePath,
    evidenceGrade: evidenceGrade ?? this.evidenceGrade,
    itemStatus: itemStatus ?? this.itemStatus,
    createdAt: createdAt ?? this.createdAt,
    updatedAt: updatedAt ?? this.updatedAt,
    servingGrams: servingGrams.present ? servingGrams.value : this.servingGrams,
    tagsJson: tagsJson ?? this.tagsJson,
    ingredientsJson: ingredientsJson ?? this.ingredientsJson,
  );
  MenuItem copyWithCompanion(MenuItemsCompanion data) {
    return MenuItem(
      id: data.id.present ? data.id.value : this.id,
      serviceId: data.serviceId.present ? data.serviceId.value : this.serviceId,
      displayName: data.displayName.present
          ? data.displayName.value
          : this.displayName,
      stationName: data.stationName.present
          ? data.stationName.value
          : this.stationName,
      rawText: data.rawText.present ? data.rawText.value : this.rawText,
      imagePath: data.imagePath.present ? data.imagePath.value : this.imagePath,
      evidenceGrade: data.evidenceGrade.present
