class Exercise extends DataClass implements Insertable<Exercise> {
  final String id;
  final String name;
  final String muscleGroup;
  final String equipment;
  final String source;

  /// 难度（docs/21 §5.5「难度」）。旧行保持 null＝未标注，读取侧
  /// 显示「难度未知」，绝不拿默认值冒充事实。
  final String? difficulty;

  /// 常用度 0–100（docs/21 §5.5「常用度」）。null 同上＝未标注。
  final int? popularity;
  final bool isUserCreated;
  final DateTime createdAt;
  final DateTime updatedAt;
  const Exercise({
    required this.id,
    required this.name,
    required this.muscleGroup,
    required this.equipment,
    required this.source,
    this.difficulty,
    this.popularity,
    required this.isUserCreated,
    required this.createdAt,
    required this.updatedAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['name'] = Variable<String>(name);
    map['muscle_group'] = Variable<String>(muscleGroup);
    map['equipment'] = Variable<String>(equipment);
    map['source'] = Variable<String>(source);
    if (!nullToAbsent || difficulty != null) {
      map['difficulty'] = Variable<String>(difficulty);
    }
    if (!nullToAbsent || popularity != null) {
      map['popularity'] = Variable<int>(popularity);
    }
    map['is_user_created'] = Variable<bool>(isUserCreated);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    return map;
  }

  ExercisesCompanion toCompanion(bool nullToAbsent) {
    return ExercisesCompanion(
      id: Value(id),
      name: Value(name),
      muscleGroup: Value(muscleGroup),
      equipment: Value(equipment),
      source: Value(source),
      difficulty: difficulty == null && nullToAbsent
          ? const Value.absent()
          : Value(difficulty),
      popularity: popularity == null && nullToAbsent
          ? const Value.absent()
          : Value(popularity),
      isUserCreated: Value(isUserCreated),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
    );
  }

  factory Exercise.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return Exercise(
      id: serializer.fromJson<String>(json['id']),
      name: serializer.fromJson<String>(json['name']),
      muscleGroup: serializer.fromJson<String>(json['muscleGroup']),
      equipment: serializer.fromJson<String>(json['equipment']),
      source: serializer.fromJson<String>(json['source']),
      difficulty: serializer.fromJson<String?>(json['difficulty']),
      popularity: serializer.fromJson<int?>(json['popularity']),
      isUserCreated: serializer.fromJson<bool>(json['isUserCreated']),
      createdAt: serializer.fromJson<DateTime>(json['createdAt']),
      updatedAt: serializer.fromJson<DateTime>(json['updatedAt']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<String>(id),
      'name': serializer.toJson<String>(name),
      'muscleGroup': serializer.toJson<String>(muscleGroup),
      'equipment': serializer.toJson<String>(equipment),
      'source': serializer.toJson<String>(source),
      'difficulty': serializer.toJson<String?>(difficulty),
      'popularity': serializer.toJson<int?>(popularity),
      'isUserCreated': serializer.toJson<bool>(isUserCreated),
      'createdAt': serializer.toJson<DateTime>(createdAt),
      'updatedAt': serializer.toJson<DateTime>(updatedAt),
    };
  }

  Exercise copyWith({
    String? id,
    String? name,
    String? muscleGroup,
    String? equipment,
    String? source,
    Value<String?> difficulty = const Value.absent(),
    Value<int?> popularity = const Value.absent(),
    bool? isUserCreated,
    DateTime? createdAt,
    DateTime? updatedAt,
  }) => Exercise(
    id: id ?? this.id,
    name: name ?? this.name,
    muscleGroup: muscleGroup ?? this.muscleGroup,
    equipment: equipment ?? this.equipment,
    source: source ?? this.source,
    difficulty: difficulty.present ? difficulty.value : this.difficulty,
    popularity: popularity.present ? popularity.value : this.popularity,
    isUserCreated: isUserCreated ?? this.isUserCreated,
    createdAt: createdAt ?? this.createdAt,
    updatedAt: updatedAt ?? this.updatedAt,
  );
  Exercise copyWithCompanion(ExercisesCompanion data) {
    return Exercise(
      id: data.id.present ? data.id.value : this.id,
      name: data.name.present ? data.name.value : this.name,
      muscleGroup: data.muscleGroup.present
          ? data.muscleGroup.value
          : this.muscleGroup,
      equipment: data.equipment.present ? data.equipment.value : this.equipment,
      source: data.source.present ? data.source.value : this.source,
      difficulty: data.difficulty.present
          ? data.difficulty.value
          : this.difficulty,
      popularity: data.popularity.present
          ? data.popularity.value
          : this.popularity,
      isUserCreated: data.isUserCreated.present
          ? data.isUserCreated.value
          : this.isUserCreated,
      createdAt: data.createdAt.present ? data.createdAt.value : this.createdAt,
      updatedAt: data.updatedAt.present ? data.updatedAt.value : this.updatedAt,
    );
  }

  @override
  String toString() {
    return (StringBuffer('Exercise(')
          ..write('id: $id, ')
          ..write('name: $name, ')
          ..write('muscleGroup: $muscleGroup, ')
          ..write('equipment: $equipment, ')
          ..write('source: $source, ')
          ..write('difficulty: $difficulty, ')
          ..write('popularity: $popularity, ')
          ..write('isUserCreated: $isUserCreated, ')
          ..write('createdAt: $createdAt, ')
          ..write('updatedAt: $updatedAt')
          ..write(')'))
        .toString();
  }

  @override
  int get hashCode => Object.hash(
    id,
    name,
    muscleGroup,
    equipment,
    source,
    difficulty,
    popularity,
    isUserCreated,
    createdAt,
    updatedAt,
  );
  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      (other is Exercise &&
          other.id == this.id &&
          other.name == this.name &&
          other.muscleGroup == this.muscleGroup &&
          other.equipment == this.equipment &&
          other.source == this.source &&
          other.difficulty == this.difficulty &&
          other.popularity == this.popularity &&
          other.isUserCreated == this.isUserCreated &&
          other.createdAt == this.createdAt &&
          other.updatedAt == this.updatedAt);
}

