class DishLibraryEntry extends DataClass
    implements Insertable<DishLibraryEntry> {
  final String id;
  final String name;
  final String? imagePath;

  /// 早餐 / 午餐 / 晚餐 / 加餐（设计稿 mealSlot）。
  final String mealSlot;

  /// 供应时段（校园窗口语义，如 06:30-09:30）；非食堂菜可空。
  final String? servingWindow;
  final bool isHot;
  final double kcal;
  final double proteinG;
  final double carbsG;
  final double fatG;
  final double? fiberG;
  final double? sodiumMg;
  final double? vitaminDMcg;
  final String source;
  final String? comment;
  final DateTime createdAt;
  final DateTime updatedAt;

  /// 一份多少克。「每份」四个营养值是 `per100g × servingGrams / 100` 的
  /// 结果（nutritionBasis 记录口径）；历史行回填 100 且 basisAssumed=1。
  final double? servingGrams;

  /// `perServing` | `per100g`（历史行回填 `perServing`）。
  final String nutritionBasis;

  /// 份量是否是假设值（UI 显示「按 100g 估算」，不假装知道份量）。
  final bool basisAssumed;

  /// `canteen` | `food` | `manual` | `imported`；null = 历史行未知。
  final String? sourceType;

  /// menuItemId / foodId（**不加外键**，允许来源删除后悬空）。
  final String? sourceId;

  /// 来源最后一次营养变更时间（用于「食堂营养有更新」提示）。
  final DateTime? sourceUpdatedAt;

  /// 用户改过营养/份量：同步时只提示、不覆盖。
  final bool userEdited;
  const DishLibraryEntry({
    required this.id,
    required this.name,
    this.imagePath,
    required this.mealSlot,
    this.servingWindow,
    required this.isHot,
    required this.kcal,
    required this.proteinG,
    required this.carbsG,
    required this.fatG,
    this.fiberG,
    this.sodiumMg,
    this.vitaminDMcg,
    required this.source,
    this.comment,
    required this.createdAt,
    required this.updatedAt,
    this.servingGrams,
    required this.nutritionBasis,
    required this.basisAssumed,
    this.sourceType,
    this.sourceId,
    this.sourceUpdatedAt,
    required this.userEdited,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['name'] = Variable<String>(name);
    if (!nullToAbsent || imagePath != null) {
      map['image_path'] = Variable<String>(imagePath);
    }
    map['meal_slot'] = Variable<String>(mealSlot);
    if (!nullToAbsent || servingWindow != null) {
      map['serving_window'] = Variable<String>(servingWindow);
    }
    map['is_hot'] = Variable<bool>(isHot);
    map['kcal'] = Variable<double>(kcal);
    map['protein_g'] = Variable<double>(proteinG);
    map['carbs_g'] = Variable<double>(carbsG);
    map['fat_g'] = Variable<double>(fatG);
    if (!nullToAbsent || fiberG != null) {
      map['fiber_g'] = Variable<double>(fiberG);
    }
    if (!nullToAbsent || sodiumMg != null) {
      map['sodium_mg'] = Variable<double>(sodiumMg);
    }
    if (!nullToAbsent || vitaminDMcg != null) {
      map['vitamin_d_mcg'] = Variable<double>(vitaminDMcg);
    }
    map['source'] = Variable<String>(source);
    if (!nullToAbsent || comment != null) {
      map['comment'] = Variable<String>(comment);
    }
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    if (!nullToAbsent || servingGrams != null) {
      map['serving_grams'] = Variable<double>(servingGrams);
    }
    map['nutrition_basis'] = Variable<String>(nutritionBasis);
    map['basis_assumed'] = Variable<bool>(basisAssumed);
    if (!nullToAbsent || sourceType != null) {
      map['source_type'] = Variable<String>(sourceType);
    }
    if (!nullToAbsent || sourceId != null) {
      map['source_id'] = Variable<String>(sourceId);
    }
    if (!nullToAbsent || sourceUpdatedAt != null) {
      map['source_updated_at'] = Variable<DateTime>(sourceUpdatedAt);
    }
    map['user_edited'] = Variable<bool>(userEdited);
    return map;
  }

