class RecognitionResult extends DataClass
    implements Insertable<RecognitionResult> {
  final String id;
  final String? mealId;
  final DateTime capturedAt;
  final String dishName;

  /// 0..1 模型置信度；UI 层按证据分级展示，不直接裸露数值。
  final double confidence;
  final String imagePath;
  final double estimatedKcal;
  final String? advice;
  final String ingredientsJson;
  final String macroJson;
  const RecognitionResult({
    required this.id,
    this.mealId,
    required this.capturedAt,
    required this.dishName,
    required this.confidence,
    required this.imagePath,
    required this.estimatedKcal,
    this.advice,
    required this.ingredientsJson,
    required this.macroJson,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    if (!nullToAbsent || mealId != null) {
      map['meal_id'] = Variable<String>(mealId);
    }
    map['captured_at'] = Variable<DateTime>(capturedAt);
    map['dish_name'] = Variable<String>(dishName);
    map['confidence'] = Variable<double>(confidence);
    map['image_path'] = Variable<String>(imagePath);
    map['estimated_kcal'] = Variable<double>(estimatedKcal);
    if (!nullToAbsent || advice != null) {
      map['advice'] = Variable<String>(advice);
    }
    map['ingredients_json'] = Variable<String>(ingredientsJson);
    map['macro_json'] = Variable<String>(macroJson);
    return map;
  }

  RecognitionResultsCompanion toCompanion(bool nullToAbsent) {
    return RecognitionResultsCompanion(
      id: Value(id),
      mealId: mealId == null && nullToAbsent
          ? const Value.absent()
          : Value(mealId),
      capturedAt: Value(capturedAt),
      dishName: Value(dishName),
      confidence: Value(confidence),
      imagePath: Value(imagePath),
      estimatedKcal: Value(estimatedKcal),
      advice: advice == null && nullToAbsent
          ? const Value.absent()
          : Value(advice),
      ingredientsJson: Value(ingredientsJson),
      macroJson: Value(macroJson),
    );
  }

  factory RecognitionResult.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return RecognitionResult(
      id: serializer.fromJson<String>(json['id']),
      mealId: serializer.fromJson<String?>(json['mealId']),
      capturedAt: serializer.fromJson<DateTime>(json['capturedAt']),
      dishName: serializer.fromJson<String>(json['dishName']),
      confidence: serializer.fromJson<double>(json['confidence']),
      imagePath: serializer.fromJson<String>(json['imagePath']),
      estimatedKcal: serializer.fromJson<double>(json['estimatedKcal']),
      advice: serializer.fromJson<String?>(json['advice']),
      ingredientsJson: serializer.fromJson<String>(json['ingredientsJson']),
      macroJson: serializer.fromJson<String>(json['macroJson']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<String>(id),
      'mealId': serializer.toJson<String?>(mealId),
      'capturedAt': serializer.toJson<DateTime>(capturedAt),
      'dishName': serializer.toJson<String>(dishName),
      'confidence': serializer.toJson<double>(confidence),
      'imagePath': serializer.toJson<String>(imagePath),
      'estimatedKcal': serializer.toJson<double>(estimatedKcal),
      'advice': serializer.toJson<String?>(advice),
      'ingredientsJson': serializer.toJson<String>(ingredientsJson),
      'macroJson': serializer.toJson<String>(macroJson),
    };
  }

  RecognitionResult copyWith({
    String? id,
    Value<String?> mealId = const Value.absent(),
    DateTime? capturedAt,
    String? dishName,
    double? confidence,
    String? imagePath,
    double? estimatedKcal,
    Value<String?> advice = const Value.absent(),
    String? ingredientsJson,
    String? macroJson,
  }) => RecognitionResult(
    id: id ?? this.id,
    mealId: mealId.present ? mealId.value : this.mealId,
    capturedAt: capturedAt ?? this.capturedAt,
    dishName: dishName ?? this.dishName,
    confidence: confidence ?? this.confidence,
    imagePath: imagePath ?? this.imagePath,
    estimatedKcal: estimatedKcal ?? this.estimatedKcal,
    advice: advice.present ? advice.value : this.advice,
    ingredientsJson: ingredientsJson ?? this.ingredientsJson,
    macroJson: macroJson ?? this.macroJson,
  );
  RecognitionResult copyWithCompanion(RecognitionResultsCompanion data) {
    return RecognitionResult(
      id: data.id.present ? data.id.value : this.id,
      mealId: data.mealId.present ? data.mealId.value : this.mealId,
      capturedAt: data.capturedAt.present
          ? data.capturedAt.value
          : this.capturedAt,
      dishName: data.dishName.present ? data.dishName.value : this.dishName,
      confidence: data.confidence.present
          ? data.confidence.value
          : this.confidence,
      imagePath: data.imagePath.present ? data.imagePath.value : this.imagePath,
      estimatedKcal: data.estimatedKcal.present
          ? data.estimatedKcal.value
          : this.estimatedKcal,
      advice: data.advice.present ? data.advice.value : this.advice,
      ingredientsJson: data.ingredientsJson.present
          ? data.ingredientsJson.value
          : this.ingredientsJson,
      macroJson: data.macroJson.present ? data.macroJson.value : this.macroJson,
    );
  }

  @override
  String toString() {
    return (StringBuffer('RecognitionResult(')
          ..write('id: $id, ')
          ..write('mealId: $mealId, ')
          ..write('capturedAt: $capturedAt, ')
          ..write('dishName: $dishName, ')
          ..write('confidence: $confidence, ')
          ..write('imagePath: $imagePath, ')
          ..write('estimatedKcal: $estimatedKcal, ')
          ..write('advice: $advice, ')
          ..write('ingredientsJson: $ingredientsJson, ')
          ..write('macroJson: $macroJson')
          ..write(')'))
        .toString();
  }

  @override
  int get hashCode => Object.hash(
    id,
    mealId,
    capturedAt,
    dishName,
    confidence,
    imagePath,
    estimatedKcal,
    advice,
    ingredientsJson,
    macroJson,
  );
  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      (other is RecognitionResult &&
          other.id == this.id &&
          other.mealId == this.mealId &&
          other.capturedAt == this.capturedAt &&
          other.dishName == this.dishName &&
          other.confidence == this.confidence &&
          other.imagePath == this.imagePath &&
          other.estimatedKcal == this.estimatedKcal &&
          other.advice == this.advice &&
          other.ingredientsJson == this.ingredientsJson &&
          other.macroJson == this.macroJson);
