class AiMemoryRow extends DataClass implements Insertable<AiMemoryRow> {
  final String id;
  final String textContent;
  final String kind;
  final String domain;
  final String tagsJson;
  final bool pinned;
  final String source;
  final String status;
  final DateTime createdAt;
  final DateTime updatedAt;
  final int importance;
  final DateTime? lastUsedAt;
  final int useCount;

  /// 改口留痕：旧条指向新条（检索只看 `active`；页面可看历史/撤销）。
  final String? supersededById;

  /// `kind=context` 的临时近况（默认 30 天）；到期**提议**归档，不自动删。
  final DateTime? expiresAt;

  /// 来源消息（`memory.remember` 从哪条对话来）——来源追溯用。
  final String? sourceMessageId;

  /// 实体链接（docs/41 G19）：`dish` | `food` | `venue`，让「不吃香菜」
  /// 能 join 到食材/菜品；没有对应实体时为 null。
  final String? linkedEntityType;
  final String? linkedEntityId;

  /// 一跳关系（可选，JSON 字符串数组）；v1 只存不用。
  final String? relatedIds;

  /// 时间语义（G23）：这条从何时成立。
  ///
  /// 历史行在迁移 29 里回填成 `created_at`（不凭空造「现在」）；新写入取
  /// 写入时刻。null 只可能出现在迁移未跑到的极旧库。
  final DateTime? validFrom;

  /// 这条到何时不再成立（改口时闭合）；null = 仍然有效。
  ///
  /// 与 `supersededById` 同时写：`supersededById` 说明「被谁取代」，
  /// `validTo` 说明「从哪一刻起不再成立」——「当时是什么」查询只读后者。
  final DateTime? validTo;
  const AiMemoryRow({
    required this.id,
    required this.textContent,
    required this.kind,
    required this.domain,
    required this.tagsJson,
    required this.pinned,
    required this.source,
    required this.status,
    required this.createdAt,
    required this.updatedAt,
    required this.importance,
    this.lastUsedAt,
    required this.useCount,
    this.supersededById,
    this.expiresAt,
    this.sourceMessageId,
    this.linkedEntityType,
    this.linkedEntityId,
    this.relatedIds,
    this.validFrom,
    this.validTo,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['text'] = Variable<String>(textContent);
    map['kind'] = Variable<String>(kind);
    map['domain'] = Variable<String>(domain);
    map['tags_json'] = Variable<String>(tagsJson);
    map['pinned'] = Variable<bool>(pinned);
    map['source'] = Variable<String>(source);
    map['status'] = Variable<String>(status);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    map['importance'] = Variable<int>(importance);
    if (!nullToAbsent || lastUsedAt != null) {
      map['last_used_at'] = Variable<DateTime>(lastUsedAt);
    }
    map['use_count'] = Variable<int>(useCount);
    if (!nullToAbsent || supersededById != null) {
      map['superseded_by_id'] = Variable<String>(supersededById);
    }
    if (!nullToAbsent || expiresAt != null) {
      map['expires_at'] = Variable<DateTime>(expiresAt);
    }
    if (!nullToAbsent || sourceMessageId != null) {
      map['source_message_id'] = Variable<String>(sourceMessageId);
    }
    if (!nullToAbsent || linkedEntityType != null) {
      map['linked_entity_type'] = Variable<String>(linkedEntityType);
    }
    if (!nullToAbsent || linkedEntityId != null) {
      map['linked_entity_id'] = Variable<String>(linkedEntityId);
    }
    if (!nullToAbsent || relatedIds != null) {
      map['related_ids'] = Variable<String>(relatedIds);
    }
    if (!nullToAbsent || validFrom != null) {
      map['valid_from'] = Variable<DateTime>(validFrom);
    }
    if (!nullToAbsent || validTo != null) {
      map['valid_to'] = Variable<DateTime>(validTo);
    }
    return map;
  }

  AiMemoriesCompanion toCompanion(bool nullToAbsent) {
    return AiMemoriesCompanion(
      id: Value(id),
      textContent: Value(textContent),
      kind: Value(kind),
      domain: Value(domain),
      tagsJson: Value(tagsJson),
      pinned: Value(pinned),
      source: Value(source),
      status: Value(status),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
      importance: Value(importance),
      lastUsedAt: lastUsedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(lastUsedAt),
      useCount: Value(useCount),
      supersededById: supersededById == null && nullToAbsent
          ? const Value.absent()
          : Value(supersededById),
      expiresAt: expiresAt == null && nullToAbsent
          ? const Value.absent()
          : Value(expiresAt),
      sourceMessageId: sourceMessageId == null && nullToAbsent
          ? const Value.absent()
          : Value(sourceMessageId),
      linkedEntityType: linkedEntityType == null && nullToAbsent
          ? const Value.absent()
          : Value(linkedEntityType),
      linkedEntityId: linkedEntityId == null && nullToAbsent
          ? const Value.absent()
          : Value(linkedEntityId),
      relatedIds: relatedIds == null && nullToAbsent
          ? const Value.absent()
          : Value(relatedIds),
      validFrom: validFrom == null && nullToAbsent
          ? const Value.absent()
          : Value(validFrom),
      validTo: validTo == null && nullToAbsent
          ? const Value.absent()
          : Value(validTo),
    );
  }

