      lastUsedAt: serializer.fromJson<DateTime?>(json['lastUsedAt']),
      useCount: serializer.fromJson<int>(json['useCount']),
      supersededById: serializer.fromJson<String?>(json['supersededById']),
      expiresAt: serializer.fromJson<DateTime?>(json['expiresAt']),
      sourceMessageId: serializer.fromJson<String?>(json['sourceMessageId']),
      linkedEntityType: serializer.fromJson<String?>(json['linkedEntityType']),
      linkedEntityId: serializer.fromJson<String?>(json['linkedEntityId']),
      relatedIds: serializer.fromJson<String?>(json['relatedIds']),
      validFrom: serializer.fromJson<DateTime?>(json['validFrom']),
      validTo: serializer.fromJson<DateTime?>(json['validTo']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<String>(id),
      'textContent': serializer.toJson<String>(textContent),
