      'updatedAt': serializer.toJson<DateTime>(updatedAt),
      'importance': serializer.toJson<int>(importance),
      'lastUsedAt': serializer.toJson<DateTime?>(lastUsedAt),
      'useCount': serializer.toJson<int>(useCount),
      'supersededById': serializer.toJson<String?>(supersededById),
      'expiresAt': serializer.toJson<DateTime?>(expiresAt),
      'sourceMessageId': serializer.toJson<String?>(sourceMessageId),
      'linkedEntityType': serializer.toJson<String?>(linkedEntityType),
      'linkedEntityId': serializer.toJson<String?>(linkedEntityId),
      'relatedIds': serializer.toJson<String?>(relatedIds),
      'validFrom': serializer.toJson<DateTime?>(validFrom),
      'validTo': serializer.toJson<DateTime?>(validTo),
    };
  }

