class BackgroundJob extends DataClass implements Insertable<BackgroundJob> {
  final String id;

  /// `dishAnalysis` | `ingredientTagging` | `sessionExtract` | `indexRebuild` …
  final String type;

  /// `pending` | `processing` | `failed`。
  final String state;
  final int attempts;
  final String? lastError;

  /// 任务参数（JSON）。
  final String payloadJson;

  /// 幂等键（如 `dishAnalysis:<menuItemId>`）：同键不重复入队。
  final String? dedupeKey;

  /// 进度 0–100（可空＝未知）。
  final int? progress;
  final DateTime createdAt;
  final DateTime updatedAt;
  const BackgroundJob({
    required this.id,
    required this.type,
    required this.state,
    required this.attempts,
    this.lastError,
    required this.payloadJson,
    this.dedupeKey,
    this.progress,
    required this.createdAt,
    required this.updatedAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['type'] = Variable<String>(type);
    map['state'] = Variable<String>(state);
    map['attempts'] = Variable<int>(attempts);
    if (!nullToAbsent || lastError != null) {
      map['last_error'] = Variable<String>(lastError);
    }
    map['payload_json'] = Variable<String>(payloadJson);
    if (!nullToAbsent || dedupeKey != null) {
      map['dedupe_key'] = Variable<String>(dedupeKey);
    }
    if (!nullToAbsent || progress != null) {
      map['progress'] = Variable<int>(progress);
    }
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    return map;
  }

  BackgroundJobsCompanion toCompanion(bool nullToAbsent) {
    return BackgroundJobsCompanion(
      id: Value(id),
      type: Value(type),
      state: Value(state),
      attempts: Value(attempts),
      lastError: lastError == null && nullToAbsent
          ? const Value.absent()
          : Value(lastError),
      payloadJson: Value(payloadJson),
      dedupeKey: dedupeKey == null && nullToAbsent
          ? const Value.absent()
          : Value(dedupeKey),
      progress: progress == null && nullToAbsent
          ? const Value.absent()
          : Value(progress),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
    );
  }

  factory BackgroundJob.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return BackgroundJob(
      id: serializer.fromJson<String>(json['id']),
      type: serializer.fromJson<String>(json['type']),
      state: serializer.fromJson<String>(json['state']),
      attempts: serializer.fromJson<int>(json['attempts']),
      lastError: serializer.fromJson<String?>(json['lastError']),
      payloadJson: serializer.fromJson<String>(json['payloadJson']),
      dedupeKey: serializer.fromJson<String?>(json['dedupeKey']),
      progress: serializer.fromJson<int?>(json['progress']),
      createdAt: serializer.fromJson<DateTime>(json['createdAt']),
      updatedAt: serializer.fromJson<DateTime>(json['updatedAt']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<String>(id),
      'type': serializer.toJson<String>(type),
      'state': serializer.toJson<String>(state),
      'attempts': serializer.toJson<int>(attempts),
      'lastError': serializer.toJson<String?>(lastError),
      'payloadJson': serializer.toJson<String>(payloadJson),
      'dedupeKey': serializer.toJson<String?>(dedupeKey),
      'progress': serializer.toJson<int?>(progress),
      'createdAt': serializer.toJson<DateTime>(createdAt),
      'updatedAt': serializer.toJson<DateTime>(updatedAt),
    };
  }

  BackgroundJob copyWith({
    String? id,
    String? type,
    String? state,
    int? attempts,
    Value<String?> lastError = const Value.absent(),
    String? payloadJson,
    Value<String?> dedupeKey = const Value.absent(),
    Value<int?> progress = const Value.absent(),
    DateTime? createdAt,
    DateTime? updatedAt,
  }) => BackgroundJob(
    id: id ?? this.id,
    type: type ?? this.type,
    state: state ?? this.state,
    attempts: attempts ?? this.attempts,
    lastError: lastError.present ? lastError.value : this.lastError,
    payloadJson: payloadJson ?? this.payloadJson,
    dedupeKey: dedupeKey.present ? dedupeKey.value : this.dedupeKey,
    progress: progress.present ? progress.value : this.progress,
    createdAt: createdAt ?? this.createdAt,
    updatedAt: updatedAt ?? this.updatedAt,
  );
  BackgroundJob copyWithCompanion(BackgroundJobsCompanion data) {
    return BackgroundJob(
      id: data.id.present ? data.id.value : this.id,
      type: data.type.present ? data.type.value : this.type,
      state: data.state.present ? data.state.value : this.state,
      attempts: data.attempts.present ? data.attempts.value : this.attempts,
      lastError: data.lastError.present ? data.lastError.value : this.lastError,
      payloadJson: data.payloadJson.present
          ? data.payloadJson.value
          : this.payloadJson,
      dedupeKey: data.dedupeKey.present ? data.dedupeKey.value : this.dedupeKey,
      progress: data.progress.present ? data.progress.value : this.progress,
      createdAt: data.createdAt.present ? data.createdAt.value : this.createdAt,
      updatedAt: data.updatedAt.present ? data.updatedAt.value : this.updatedAt,
    );
  }

  @override
  String toString() {
    return (StringBuffer('BackgroundJob(')
          ..write('id: $id, ')
          ..write('type: $type, ')
          ..write('state: $state, ')
          ..write('attempts: $attempts, ')
          ..write('lastError: $lastError, ')
          ..write('payloadJson: $payloadJson, ')
          ..write('dedupeKey: $dedupeKey, ')
          ..write('progress: $progress, ')
          ..write('createdAt: $createdAt, ')
          ..write('updatedAt: $updatedAt')
          ..write(')'))
        .toString();
  }

  @override
  int get hashCode => Object.hash(
    id,
    type,
    state,
    attempts,
    lastError,
    payloadJson,
    dedupeKey,
    progress,
    createdAt,
    updatedAt,
  );
  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      (other is BackgroundJob &&
          other.id == this.id &&
          other.type == this.type &&
          other.state == this.state &&
          other.attempts == this.attempts &&
          other.lastError == this.lastError &&
          other.payloadJson == this.payloadJson &&
          other.dedupeKey == this.dedupeKey &&
          other.progress == this.progress &&
          other.createdAt == this.createdAt &&
          other.updatedAt == this.updatedAt);
}

